<script lang="ts">
 import { onMount } from 'svelte';
 import Button from '$lib/ui/button/button.svelte';
 import { datasetStore, initializeDataset } from '$lib/engine/dataset/store.svelte';
 import { createEditorState, downloadDataset, addCompetition, addSeason, addTeam, addPlayer, addMembership, addTeamSnapshot, addPlayerSnapshot, addChemistryPair, removeCompetition, removeSeason, removeTeam, removePlayer, removeMembership } from '$lib/dataset-editor';
 import { seedBundesliga } from '$lib/dataset-editor/seed-bundesliga';
 import type { FootballDataset } from '$lib/engine/dataset/types';

 let editor: ReturnType<typeof createEditorState> | null = $state(null);
 let selected = $state('competitions');
 let competitionName = $state(''); let seasonName = $state(''); let teamName = $state(''); let playerName = $state('');
 let membershipPlayer = $state(''); let membershipTeam = $state(''); let membershipFrom = $state('2026-08-01');
 let status = $state('');
 const tabs = ['competitions', 'seasons', 'teams', 'players', 'memberships', 'snapshots', 'chemistry', 'matches', 'provenance'];
 onMount(() => { initializeDataset(); editor = createEditorState(datasetStore.dataset ?? undefined); });
 function update(fn: (dataset: FootballDataset) => FootballDataset) { if (editor) editor.replace(fn(editor.dataset)); }
 function addCompetitionEntry() { if (!competitionName.trim()) return; update((d) => addCompetition(d, { name: competitionName, shortName: competitionName.slice(0, 3).toUpperCase(), type: 'league', countryCode: 'XX', level: 1, gender: 'mixed', seasonIds: [] })); competitionName = ''; }
 function addSeasonEntry() { if (!seasonName.trim() || !editor?.dataset.competitions[0]) return; update((d) => addSeason(d, { competitionId: d.competitions[0].id, name: seasonName, startDate: '2026-08-01', endDate: '2027-05-31' })); seasonName = ''; }
 function addTeamEntry() { if (!teamName.trim()) return; update((d) => addTeam(d, { canonicalName: teamName, shortName: teamName.slice(0, 3).toUpperCase(), countryCode: 'XX', aliases: [] })); teamName = ''; }
 function addPlayerEntry() { if (!playerName.trim()) return; update((d) => addPlayer(d, { canonicalName: playerName, nationalityCodes: [], positions: [], status: 'unknown' })); playerName = ''; }
 function addMembershipEntry() { if (!membershipPlayer || !membershipTeam) return; update((d) => addMembership(d, { playerId: membershipPlayer, teamId: membershipTeam, role: 'player', contractType: 'unknown', validFrom: membershipFrom, validTo: null })); }
 function addSnapshotEntry() { if (!editor) return; const d = editor.dataset; if (d.teams[0]) update((x) => addTeamSnapshot(x, { teamId: d.teams[0].id, validFrom: '2026-08-01', validTo: null, rating: { elo: 1600 } })); if (d.players[0]) update((x) => addPlayerSnapshot(x, { playerId: d.players[0].id, validFrom: '2026-08-01', validTo: null, scale: { min: 1, max: 20 }, ability: { current: 70, potential: 80 }, attributes: {}, assessmentType: 'estimated' })); }
 function addChemistryEntry() { const team = editor?.dataset.teams[0]; if (!team) return; update((d) => addChemistryPair(d, { id: 'chemistry-editor-entry', teamId: team.id, validFrom: '2026-08-01', validTo: null, overall: 0.7 })); }
 function addMatchEntry() { const d = editor?.dataset; if (!d || d.teams.length < 2 || !d.competitions[0] || !d.seasons[0]) return; update((x) => ({ ...x, matches: [...x.matches, { id: `match-editor-${x.matches.length + 1}`, competitionId: x.competitions[0].id, seasonId: x.seasons[0].id, dateTime: '2026-08-01T15:30:00Z', homeTeamId: x.teams[0].id, awayTeamId: x.teams[1].id, status: 'scheduled' }] })); }
 function addProvenanceEntry() { update((d) => ({ ...d, provenance: [...d.provenance, { id: `provenance-editor-${d.provenance.length + 1}`, type: 'manual', provider: 'Felix Kramer', name: 'Manual editor record', license: 'CC0-1.0', method: 'Entered in dataset editor.' }] })); }
 function removeFrom(collection: keyof FootballDataset, id: string) { update((d) => ({ ...d, [collection]: (d[collection] as Array<{ id: string }>).filter((entry) => entry.id !== id) } as FootballDataset)); }
 function seed() { editor?.replace(seedBundesliga()); selected = 'teams'; status = 'Synthetic Bundesliga seeded'; }
 function exportFile() { if (!editor) return; if (!editor.validate()) { status = 'Fix validation errors before exporting'; return; } downloadDataset(editor.dataset); status = 'Dataset exported'; }
</script>
<svelte:head><title>Dataset editor — Felix Kramer</title><meta name="description" content="Internal football dataset creation tool" /></svelte:head>
<div class="mx-auto max-w-6xl px-4 py-10">
 <div class="flex flex-wrap items-start justify-between gap-4"><div><h1 class="text-3xl font-bold text-ink">Dataset editor</h1><p class="mt-2 text-ink-secondary">Create and validate a local FootballDataset.</p></div><div class="flex flex-wrap gap-2"><Button variant="secondary" disabled={!editor} onclick={seed}>Seed Bundesliga</Button><Button variant="secondary" disabled={!editor} onclick={exportFile}>Export JSON</Button><Button variant="icon-outline" aria-label="Reset to loaded dataset" disabled={!editor} onclick={() => editor?.reset()}>↺</Button></div></div>
 {#if editor}<div class="mt-6 rounded-xl border border-line bg-surface p-4">
  <div class="flex flex-wrap gap-2" role="tablist" aria-label="Dataset sections">{#each tabs as tab}<button type="button" role="tab" class="rounded-full px-4 py-2 text-sm font-bold {selected === tab ? 'bg-accent text-on-teal' : 'border border-line text-ink-secondary'}" aria-selected={selected === tab} onclick={() => selected = tab}>{tab[0].toUpperCase() + tab.slice(1)}</button>{/each}</div>
  {#if selected === 'competitions'}<section class="mt-6"><h2 class="text-xl font-semibold">Competitions</h2><form class="mt-3 flex gap-2" onsubmit={(e) => { e.preventDefault(); addCompetitionEntry(); }}><input class="rounded border border-line bg-transparent px-3 py-2" aria-label="Competition name" placeholder="Name" bind:value={competitionName} /><Button type="submit">Add</Button></form><ul class="mt-4 space-y-2">{#each editor.dataset.competitions as e (e.id)}<li class="flex justify-between rounded border border-line px-3 py-2"><span>{e.name} <small class="text-ink-tertiary">{e.id}</small></span><Button variant="destructive" onclick={() => update((d) => removeCompetition(d, e.id))}>Remove</Button></li>{:else}<li>No competitions yet.</li>{/each}</ul></section>
  {:else if selected === 'seasons'}<section class="mt-6"><h2 class="text-xl font-semibold">Seasons</h2><form class="mt-3 flex gap-2" onsubmit={(e) => { e.preventDefault(); addSeasonEntry(); }}><input class="rounded border border-line bg-transparent px-3 py-2" aria-label="Season name" placeholder="2026/27" bind:value={seasonName} /><Button type="submit">Add</Button></form><ul class="mt-4 space-y-2">{#each editor.dataset.seasons as e (e.id)}<li class="flex justify-between rounded border border-line px-3 py-2"><span>{e.name} · {e.startDate} – {e.endDate}</span><Button variant="destructive" onclick={() => update((d) => removeSeason(d, e.id))}>Remove</Button></li>{:else}<li>No seasons yet.</li>{/each}</ul></section>
  {:else if selected === 'teams'}<section class="mt-6"><h2 class="text-xl font-semibold">Teams</h2><form class="mt-3 flex gap-2" onsubmit={(e) => { e.preventDefault(); addTeamEntry(); }}><input class="rounded border border-line bg-transparent px-3 py-2" aria-label="Team name" placeholder="Canonical name" bind:value={teamName} /><Button type="submit">Add</Button></form><ul class="mt-4 space-y-2">{#each editor.dataset.teams as e (e.id)}<li class="flex justify-between rounded border border-line px-3 py-2"><span>{e.canonicalName} <small class="text-ink-tertiary">{e.shortName}</small></span><Button variant="destructive" onclick={() => update((d) => removeTeam(d, e.id))}>Remove</Button></li>{/each}</ul></section>
  {:else if selected === 'players'}<section class="mt-6"><h2 class="text-xl font-semibold">Players</h2><form class="mt-3 flex gap-2" onsubmit={(e) => { e.preventDefault(); addPlayerEntry(); }}><input class="rounded border border-line bg-transparent px-3 py-2" aria-label="Player name" placeholder="Canonical name" bind:value={playerName} /><Button type="submit">Add</Button></form><ul class="mt-4 space-y-2">{#each editor.dataset.players as e (e.id)}<li class="flex justify-between rounded border border-line px-3 py-2"><span>{e.canonicalName} · {e.positions.join(', ')}</span><Button variant="destructive" onclick={() => update((d) => removePlayer(d, e.id))}>Remove</Button></li>{:else}<li>No players yet.</li>{/each}</ul></section>
  {:else if selected === 'memberships'}<section class="mt-6"><h2 class="text-xl font-semibold">Memberships</h2><form class="mt-3 flex flex-wrap gap-2" onsubmit={(e) => { e.preventDefault(); addMembershipEntry(); }}><select class="rounded border border-line bg-transparent px-3 py-2" aria-label="Player" bind:value={membershipPlayer}><option value="">Player</option>{#each editor.dataset.players as p}<option value={p.id}>{p.canonicalName}</option>{/each}</select><select class="rounded border border-line bg-transparent px-3 py-2" aria-label="Team" bind:value={membershipTeam}><option value="">Team</option>{#each editor.dataset.teams as t}<option value={t.id}>{t.canonicalName}</option>{/each}</select><Button type="submit">Add</Button></form><ul class="mt-4 space-y-2">{#each editor.dataset.memberships as e (e.id)}<li class="flex justify-between rounded border border-line px-3 py-2"><span>{e.playerId} → {e.teamId}</span><Button variant="destructive" onclick={() => update((d) => removeMembership(d, e.id))}>Remove</Button></li>{/each}</ul></section>
  {:else if selected === 'snapshots'}<section class="mt-6"><h2 class="text-xl font-semibold">Snapshots</h2><Button class="mt-3" onclick={addSnapshotEntry}>Add sample snapshots</Button><h3 class="mt-5 font-semibold">Team snapshots</h3><ul class="mt-2 space-y-2">{#each editor.dataset.teamSnapshots as e (e.id)}<li class="flex justify-between rounded border border-line px-3 py-2"><span>{e.teamId} · ELO {e.rating.elo}</span><Button variant="destructive" onclick={() => removeFrom('teamSnapshots', e.id)}>Remove</Button></li>{/each}</ul><h3 class="mt-5 font-semibold">Player snapshots</h3><ul class="mt-2 space-y-2">{#each editor.dataset.playerSnapshots as e (e.id)}<li class="flex justify-between rounded border border-line px-3 py-2"><span>{e.playerId} · ability {e.ability?.current ?? '—'}</span><Button variant="destructive" onclick={() => removeFrom('playerSnapshots', e.id)}>Remove</Button></li>{/each}</ul></section>
  {:else if selected === 'chemistry'}<section class="mt-6"><h2 class="text-xl font-semibold">Chemistry</h2><Button class="mt-3" onclick={addChemistryEntry}>Add sample</Button><ul class="mt-4 space-y-2">{#each editor.dataset.chemistry as e (e.id)}<li class="flex justify-between rounded border border-line px-3 py-2"><span>{e.teamId} · overall {e.overall}</span><Button variant="destructive" onclick={() => removeFrom('chemistry', e.id)}>Remove</Button></li>{/each}</ul></section>
  {:else if selected === 'matches'}<section class="mt-6"><h2 class="text-xl font-semibold">Matches</h2><Button class="mt-3" onclick={addMatchEntry}>Add sample</Button><ul class="mt-4 space-y-2">{#each editor.dataset.matches as e (e.id)}<li class="flex justify-between rounded border border-line px-3 py-2"><span>{e.dateTime.slice(0, 10)} · {e.homeTeamId} {e.score?.home ?? '–'}:{e.score?.away ?? '–'} {e.awayTeamId}</span><Button variant="destructive" onclick={() => removeFrom('matches', e.id)}>Remove</Button></li>{:else}<li>No matches yet.</li>{/each}</ul></section>
  {:else}<section class="mt-6"><h2 class="text-xl font-semibold">Provenance</h2><Button class="mt-3" onclick={addProvenanceEntry}>Add record</Button><ul class="mt-4 space-y-2">{#each editor.dataset.provenance as e (e.id)}<li class="flex justify-between rounded border border-line px-3 py-2"><span>{e.name} · {e.provider}</span><Button variant="destructive" onclick={() => removeFrom('provenance', e.id)}>Remove</Button></li>{:else}<li>No provenance records yet.</li>{/each}</ul></section>{/if}
 </div>
 <section class="mt-6 rounded-xl border border-line bg-surface p-4"><div class="flex items-center justify-between"><h2 class="text-xl font-semibold">Validation</h2><Button variant="secondary" onclick={() => editor?.validate()}>Validate</Button></div>{#if editor.issues.length === 0}<p class="mt-3 text-accent" role="status">Dataset is valid and ready to export.</p>{:else}<ul class="mt-3 space-y-1 text-sm text-coral" role="alert">{#each editor.issues as issue}<li><code>{issue.path || '$'}</code>: {issue.message}</li>{/each}</ul>{/if}{#if status}<p class="mt-3 text-sm text-ink-tertiary" role="status">{status}</p>{/if}</section>
 {:else}<p class="mt-8 text-ink-secondary">Loading dataset…</p>{/if}
</div>
